import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {PasteTargetComponent} from "./pasteTarget.component";
import {PASTE_TARGET_ACTION, PASTE_TARGET_CARD} from "./pasteTarget.types";

export * from "./pasteTarget.types";

registerCardComponent({
  name: PASTE_TARGET_CARD,
  component: PasteTargetComponent,
  events: actionTypesToEvents(PASTE_TARGET_ACTION),
});

import {
  DEF_ERROR_COLOR,
  DEF_EVENT_DURATION_SECONDS,
  DEF_HEIGHT,
  DEF_OVERLAY_OPACITY,
  DEF_PASTE_FIRST_REMINDER,
  DEF_SUCCESS_COLOR,
  PasteItem,
  PasteTargetEvents,
  PasteTargetProps,
} from "@/cards/pasteTarget/pasteTarget.types";
import {PiCardProps} from "@pihanga2/core";
import React, {useRef, useState} from "react";

import "./pasteTarget.css";
import clsx from "clsx";
import {Button} from "@/components/ui/button";

// /* 3. Stretch the child to cover the parent entirely */
// top: 0,
// left: 0,
// right: 0,
// bottom: 0,

// /* 4. Ensure the child is visually stacked above the parent's content */
// z-index: 10,

// /* Optional: Make the overlay visible (e.g., semi-transparent black) */
// overlayOpacity: "rgba(0, 0, 0, 0.5)";
// }

export const PasteTargetComponent = (
  props: PiCardProps<PasteTargetProps, PasteTargetEvents>,
): React.ReactNode => {
  const {
    title, //  = "Paste content right here",
    description,
    pasteFirstReminder = DEF_PASTE_FIRST_REMINDER,
    withUpload,

    height = DEF_HEIGHT,

    onPastedContent,

    successColor = DEF_SUCCESS_COLOR,
    errorColor = DEF_ERROR_COLOR,
    eventDurationSeconds = DEF_EVENT_DURATION_SECONDS,
    eventOpacity = DEF_OVERLAY_OPACITY,
    cardName,
    className,
    _cls,
  } = props;
  const [overlayOpacity, setOverlayOpacity] = useState<number>(0);
  const [overlayBackground, setOverlayBackground] = useState<string>("gray");
  const timerRef = React.useRef<number | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [isFocused, setIsFocused] = useState<boolean>(false);

  const overlayStyle: React.CSSProperties = {
    backgroundColor: overlayBackground,
    opacity: overlayOpacity,
  };

  const handlePaste = (event: React.ClipboardEvent<HTMLTextAreaElement>) => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }

    event.preventDefault();
    const clipboardData =
      event.clipboardData ||
      (window as Window & {clipboardData?: DataTransfer}).clipboardData;

    if (clipboardData) {
      const pItems = clipboardData.items;
      const items: PasteItem[] = [];
      for (let i = 0; i < pItems.length; i++) {
        const pi = pItems[i];
        const mimeType = pi.type;
        const content = clipboardData.getData(pi.type);
        if (!(content == "" || content == "\n")) {
          items.push({mimeType, content});
        }
      }
      onPastedContent({items});
      setOverlayBackground(successColor);
    } else {
      setOverlayBackground(errorColor);
    }
    setOverlayOpacity(eventOpacity);
    if (textareaRef.current) textareaRef.current.blur();

    // Set a timeout to switch the color back after 'n' seconds
    const newTimerId = setTimeout(() => {
      setOverlayOpacity(0);
      timerRef.current = null; // Clear the ref after the timeout executes
    }, eventDurationSeconds * 1000); // Convert seconds to milliseconds

    // Save the new timer ID to the ref (unknown necessary type casting)
    timerRef.current = newTimerId as unknown as number;
  };

  // Cleanup function to clear the timer when the component unmounts
  React.useEffect(() => {
    return () => {
      const ref = timerRef.current;
      if (ref) {
        clearTimeout(ref);
      }
    };
  }, []); // runs only on mount/unmount

  function renderPasteHandler() {
    return (
      <textarea
        onPaste={handlePaste}
        onFocus={() => {
          console.log("...focused");
          setIsFocused(true);
        }}
        onBlur={() => setIsFocused(false)}
        style={overlayStyle}
        // 🔑 CRUCIAL: Auto-focus the element so it's ready to receive the paste event.
        // autoFocus
        readOnly
        ref={textareaRef}
      />
    );
  }

  function onUpload(ev: React.MouseEvent<HTMLButtonElement>) {
    console.log("Clicked!!!");
    ev.stopPropagation();
    ev.preventDefault();
  }

  function renderTitle() {
    if (title) {
      return <h2 className="paste-target-msg-title">{title}</h2>;
    } else {
      return (
        <div className="paste-target-msg-title">
          Paste
          {!isFocused && withUpload && (
            <>
              &nbsp;or&nbsp;
              <Button
                onClick={onUpload}
                style={{position: "relative", zIndex: 30}}
              >
                Upload
              </Button>
            </>
          )}
          &nbsp;Specification here
        </div>
      );
    }
  }

  const cn = _cls("root", className || "pihanga-paste-target");

  return (
    <div
      className={clsx(cn, isFocused && "pihanga-paste-target-focused")}
      data-pihanga={cardName}
      style={{position: "relative", height}}
    >
      <div className="paste-target-label">
        {renderTitle()}
        {description && (
          <span className="paste-target-msg-desc">{description}</span>
        )}
        <div className="paste-target-focus-reminder">{pasteFirstReminder}</div>
      </div>
      {renderPasteHandler()}
    </div>
  );
};

.pihanga-paste-target {

  border: dashed 2px #999;

  .paste-target-msg-title {
    font-size: 1.2em
  }

  .paste-target-label {
    position: absolute;

    /* Stretch the child to cover the parent entirely */
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;

    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    width: 100%;
  }

  textarea {
    position: absolute;

    /* Stretch the child to cover the parent entirely */
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;

    /* Ensure the child is visually stacked above the parent's content */
    z-index: 10;

    cursor: pointer;
  }

  textarea:focus {
    cursor: copy;

    /* Remove the default focus outline for a cleaner look (optional but common) */
    outline: none;
  }
}

.pihanga-paste-target-focused {
  /* Change the border color to highlight the active element */
  border-color: #007bff;
  border-width: 3px;

  .paste-target-focus-reminder {
    display: none
  }
}


import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PASTE_TARGET_CARD = "paste-target";
export const PasteTarget = createCardDeclaration<
  PasteTargetProps,
  PasteTargetEvents
>(PASTE_TARGET_CARD);

export const PASTE_TARGET_ACTION = registerActions(PASTE_TARGET_CARD, [
  "pasted_content",
  "error",
]);

export const onContentPasted = createOnAction<CloseEvent>(
  PASTE_TARGET_ACTION.PASTED_CONTENT
);

export const onPasteError = createOnAction<PasteTargetErrorEvent>(
  PASTE_TARGET_ACTION.ERROR
);

export const DEF_HEIGHT = "120px";
export const DEF_SUCCESS_COLOR = "lightgreen";
export const DEF_ERROR_COLOR = "lightred";
export const DEF_EVENT_DURATION_SECONDS = 1;
export const DEF_OVERLAY_OPACITY = 0.5;

export const DEF_PASTE_FIRST_REMINDER =
  "(Before pasting, click this this box to get the focus)";

export type PasteTargetProps = {
  fileTypes?: string[];
  title?: string;
  description?: string;
  pasteFirstReminder?: string;
  withUpload?: boolean;

  height?: string | number;

  successColor?: string;
  errorColor?: string;
  eventDurationSeconds?: number; // How long to show success/error overlay color
  eventOpacity?: number; // Opacity of overlay on paste event

  className?: string;
};

export const DEF_PASTE_TARGET_FILE_TYPES = ["JPG", "PNG", "GIF"];

export type PasteItem = {
  mimeType: string;
  content: string;
};

export type PasteTargetPastedEvent = {
  items: PasteItem[];
};

export type PasteTargetErrorEvent = {
  error: string;
};

export type PasteTargetEvents = {
  onPastedContent: PasteTargetPastedEvent;
  onError: PasteTargetErrorEvent;
};
